/* Mongolian Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Bat": "firm, strong — Mongolian", "Bold": "steel — Mongolian", "Oyuun": "wisdom — Mongolian", "Naran": "sun — Mongolian", "Temujin": "of iron — Mongolian temur", "Altan": "gold — Mongolian altan", "Borjigin": "The clan of Genghis Khan, revived as a surname since the 1990s.", "Patronymic -iin": "Mongolians use the father's name in the genitive, as in Batyn (of Bat), instead of a fixed surname.", "Ovog revival": "Since the 1990s Mongolians have reclaimed clan names (ovog) as surnames.", "-ov Soviet forms": "Soviet-era Mongolian surnames took Russian -ov/-ev endings, now largely dropped."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Bat';
console.log(lookup(q));

